create database Customer_shoping;
use Customer_shoping;
select * from Customer;
-- 1. Revenue Analysis -
-- Compared total revenue generated by male and female customeras.
select gender , sum(purchase_amount) as total_revenue from Customer
group by gender;

-- 2. Discount & Spending Analysis -
-- Identified discounted user whose purchase amounts were at or above the overall average  
select customer_id , purchase_amount from Customer
where discount_applied = 'Yes'
and purchase_amount>=(select avg(purchase_amount) from Customer)

-- 3. Product Rating Analysis -
-- Ranked the top 5 products by average review rating.
select top 5 item_purchased, round(AVG(review_rating),2) as "Average Product Rating" from Customer
group by item_purchased
order by AVG(review_rating)  desc;

-- 4. Shipping Analysis -
-- Compared average purchase amounts for Standard and Express shipping.
select shipping_type,avg(purchase_amount) as "Average Purchase Amount" from Customer
where shipping_type in ('Standard','Express')
GROUP BY shipping_type;
select AVG(purchase_amount) from Customer

-- 5. Subscription Analysis -
-- Compared custumer counts ,average spending, and total revenue between subscribers 
-- and non-subscribers.
select subscription_status, count(customer_id) as "Customer Count", 
avg(purchase_amount) as "Average Spending", 
sum(purchase_amount) as "Total Revenue" from Customer
    group by subscription_status
-- 6. Discount Dependency Analysis -
-- Identified the top 5 product by percentage of purchases with discount applied.
 select top 5 item_purchased, round(
 100*sum(
    case when discount_applied = 'Yes' then 1 else 0 end )
    /count(*),2) as discount_rate
     from Customer
     group by item_purchased
     order by discount_rate desc
--7.Customer Segmentation Analysis -
-- Classified customers into new , Returning, and loyal segments based on previous purchases
 ;with custumer_type as 
    (select customer_id,previous_purchases,
       case 
       when previous_purchases=1 then 'New'
       when previous_purchases between 2 and 10 then 'Returning' 
       else 'Loyal' 
       end as customer_segment 
      from Customer 
 )
 select customer_segment,count(*) as Number_of_Customers  from custumer_type
 group by customer_segment     
 
-- 8. Product Popularity Analysis -
-- Identified the top 3 most purchased product within each category.
;with item_counts as
 (select category,
  item_purchased,
  count(customer_id) as total_orders,
  ROW_NUMBER() over (partition by category order by count(customer_id) desc) as item_rank
  from Customer
  group by category,item_purchased
  )
select item_rank ,category,item_purchased,total_orders from item_counts
  where item_rank<=3

-- 9.Repeat Buyer Analysis -
--Compared subscription status among customers with more than 5 previous purchases
select subscription_status,count(customer_id) as "Repeated_buyers" from Customer
where previous_purchases>5
group by subscription_status

-- 10.Age Group Revenue Analysis -
-- Compared total revenue across customer age groups.
select age_group,sum(purchase_amount) as Total_revenue 
from Customer
group by age_group
order by Total_revenue desc
